import base64, json, os

# ── Decode file contents ──────────────────────────────────────────────────────
CAL = base64.b64decode("").decode('utf-8')
COM = base64.b64decode("").decode('utf-8')
NEW_KEYS = json.loads(base64.b64decode("").decode('utf-8'))

# ── Write Dart files ──────────────────────────────────────────────────────────
for path, content in [
    (r'lib\features\calendar\calendar_page.dart', CAL),
    (r'lib\features\community\community_page.dart', COM),
]:
    with open(path, 'w', encoding='utf-8', newline='\n') as f:
        f.write(content)
    print(f'Written: {path}')

# ── Update ARB files ──────────────────────────────────────────────────────────
for fname, keys in NEW_KEYS.items():
    fpath = os.path.join('lib', 'l10n', fname)
    try:
        with open(fpath, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception:
        # File might be corrupted - rebuild from scratch with known keys
        data = {}
    added = 0
    for k, v in keys.items():
        if k not in data:
            data[k] = v
            added += 1
    with open(fpath, 'w', encoding='utf-8', newline='\n') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
        f.write('\n')
    print(f'{fname}: +{added} keys')

print('\nDone! Run: flutter run')
